begin;
do $$declare mid uuid:=gen_random_uuid();begin
 insert into auth.users(id,email,raw_app_meta_data) values(mid,mid||'@example.invalid',jsonb_build_object('poker_account',true,'poker_username','Test_'||substr(replace(mid::text,'-',''),1,20)));
 update public.poker_accounts set approved=true where user_id=mid;
 perform set_config('test.member',mid::text,true);
 perform set_config('test.owner',(select user_id::text from public.poker_accounts where role='owner'),true);
end;$$;
set local role authenticated;
do $$declare oid text:=current_setting('test.owner');mid text:=current_setting('test.member');sid uuid:=gen_random_uuid();snap jsonb;s jsonb;c jsonb;op uuid:=gen_random_uuid();denied boolean;begin
 perform set_config('request.jwt.claim.sub',oid,true);snap:=public.poker_snapshot();
 assert exists(select 1 from jsonb_array_elements(snap->'players') p where p->>'id'=mid and p->>'accountId'=mid),'Cadastro cria perfil';
 assert not exists(select 1 from jsonb_array_elements(snap->'players') p where p->>'accountId' is null and (p->>'active')::boolean),'Legados inativos';
 c:=jsonb_build_object('id',op,'type','create','payload',jsonb_build_object('id',sid,'name','Teste colaborativo','ancient','Responsável','startedAt','2026-10-26T12:00:00Z','mode','full','variant','texas','buyin',500,'rebuy',500,'chips',snap->'settings'->'chips','players',jsonb_build_array(oid,mid)));
 perform public.poker_command(c);perform public.poker_command(c);
 assert (public.poker_operation_status(op)->>'applied')::boolean,'Recibo idempotente';
 select x into s from jsonb_array_elements(public.poker_snapshot()->'sessions') x where x->>'id'=sid::text;
 assert jsonb_array_length(s->'entries')=2,'Sem duplicar entradas';
 perform set_config('request.jwt.claim.sub',mid,true);
 assert not (public.poker_operation_status(op)->>'applied')::boolean,'Recibo isolado';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','count','sessionId',sid,'expectedRevision',1,'payload',jsonb_build_object('playerId',mid,'expectedCountRevision',0,'quantities',jsonb_build_array(0,0,0,10,5),'useFinal',true)));
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','count','sessionId',sid,'payload',jsonb_build_object('playerId',oid,'expectedCountRevision',0,'quantities',jsonb_build_array(0,0,0,0,0),'useFinal',true)));exception when insufficient_privilege then denied:=true;end;assert denied,'Nao altera outro';
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','settings','payload',snap->'settings'));exception when insufficient_privilege then denied:=true;end;assert denied,'Nao configura banco';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','preferences','payload',jsonb_build_object('chips',jsonb_set(snap->'settings'->'chips','{0,color}','"#123456"'),'reducedMotion',true)));
 assert public.poker_snapshot()->'account'->'preferences'->'chips'->0->>'color'='#123456','Cor propria salva';
 perform set_config('request.jwt.claim.sub',oid,true);
 assert public.poker_snapshot()->'account'->'preferences'->'chips'->0->>'color' is distinct from '#123456','Cor isolada';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','count','sessionId',sid,'expectedRevision',1,'payload',jsonb_build_object('playerId',oid,'expectedCountRevision',0,'quantities',jsonb_build_array(0,0,0,0,0),'useFinal',true)));
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','count','sessionId',sid,'expectedRevision',1,'payload',jsonb_build_object('playerId',mid,'expectedCountRevision',0,'quantities',jsonb_build_array(0,0,0,0,0),'useFinal',true)));exception when serialization_failure then denied:=true;end;assert denied,'Conflito mesmo jogador';
 select x into s from jsonb_array_elements(public.poker_snapshot()->'sessions') x where x->>'id'=sid::text;
 assert s->'finals'->>mid='1000' and s->'finals'->>oid='0','Simultaneidade e zero';
 assert jsonb_array_length(s->'entries')=2,'Contagem nao altera financeiro';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','finalize','sessionId',sid,'expectedRevision',s->'revision','payload','{}'::jsonb));
 perform set_config('request.jwt.claim.sub',mid,true);
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','final','sessionId',sid,'payload',jsonb_build_object('playerId',mid,'expectedCountRevision',1,'amount',0)));exception when others then denied:=true;end;assert denied,'Fechada bloqueia contagem';
end;$$;
rollback;
select 'PASS: cadastro, entrada idempotente, permissões, contagens independentes, conflito, zero, cores e fechamento' as resultado;
